    $categories = ['people'=>'افراد','machine'=>'ماشین','method'=>'روش','material'=>'مواد','environment'=>'محیط','management'=>'مدیریت'];
    $fishboneData = $incident->fishbone ?? [];
    $treeData = $incident->fault_tree ?? [];
    $treeNodes = [];
    foreach ($treeData as $index => $node) {
        if (is_array($node)) {
            $treeNodes[] = ['id'=>$node['id'] ?? 'node-'.$index, 'label'=>$node['label'] ?? '', 'parent_id'=>$node['parent_id'] ?? null, 'relation'=>$node['relation'] ?? 'OR'];
        } elseif (filled($node)) {
            $treeNodes[] = ['id'=>'node-'.$index, 'label'=>$node, 'parent_id'=>$index ? 'node-'.($index - 1) : null, 'relation'=>'OR'];
        }
    }
    if (!$treeNodes) $treeNodes[] = ['id'=>'root', 'label'=>'رویداد نهایی', 'parent_id'=>null, 'relation'=>'OR'];
@endphp
