<script>
(() => {
    const methodSelect = document.getElementById('rca-method');
    const panels = document.querySelectorAll('[data-rca-panel]');
    const syncPanels = () => { const method = methodSelect.value; panels.forEach(panel => { const active = method === 'combined' || method === panel.dataset.rcaPanel; panel.classList.toggle('hidden', !active); panel.querySelectorAll('input,select,textarea').forEach(input => { input.disabled = !active; }); }); };
    methodSelect?.addEventListener('change', syncPanels); syncPanels();
    document.querySelectorAll('[data-add-cause]').forEach(button => button.addEventListener('click', () => { const list = document.querySelector(`[data-fishbone-category="${button.dataset.addCause}"]`); const row = document.createElement('div'); row.className = 'flex gap-2'; row.innerHTML = `<input name="fishbone[${button.dataset.addCause}][]" placeholder="علت جدید" class="w-full rounded-lg border p-2 text-sm"><button type="button" data-remove-row class="px-2 text-rose-500" title="حذف علت">×</button>`; list.appendChild(row); }));
    document.addEventListener('click', event => { if (event.target.matches('[data-remove-row]')) event.target.closest('.flex')?.remove(); if (event.target.matches('[data-remove-node]')) { event.target.closest('[data-tree-node]')?.remove(); refreshParents(); } });
    const treeList = document.getElementById('fault-tree-nodes'); const template = document.getElementById('tree-node-template');
    const refreshParents = () => { const nodes = [...treeList.querySelectorAll('[data-tree-node]')]; nodes.forEach((node, index) => { const idInput = node.querySelector('[data-tree-id]'); const id = idInput.value || `node-${Date.now()}-${index}`; idInput.value = id; node.querySelectorAll('[name]').forEach(input => { input.name = input.name.replace(/nodes\]\[\d+\]/, `nodes][${index}]`); }); const select = node.querySelector('[data-tree-parent]'); const current = select.value; select.innerHTML = '<option value="">والد اصلی</option>'; nodes.forEach(parent => { if (parent !== node) { const parentId = parent.querySelector('[data-tree-id]').value; const label = parent.querySelector('[data-tree-label], [name$="[label]"]')?.value || parentId; const option = new Option(label, parentId); option.selected = parentId === current; select.add(option); } }); }); };
    document.getElementById('add-tree-node')?.addEventListener('click', () => { const index = treeList.querySelectorAll('[data-tree-node]').length; const node = template.content.cloneNode(true); const wrapper = node.querySelector('[data-tree-node]'); wrapper.querySelector('[data-tree-id]').name = `fault_tree[nodes][${index}][id]`; wrapper.querySelector('[data-tree-id]').value = `node-${Date.now()}`; wrapper.querySelector('[data-tree-label]').name = `fault_tree[nodes][${index}][label]`; wrapper.querySelector('[data-tree-parent]').name = `fault_tree[nodes][${index}][parent_id]`; wrapper.querySelector('[data-tree-relation]').name = `fault_tree[nodes][${index}][relation]`; treeList.appendChild(node); refreshParents(); });
    treeList?.addEventListener('input', event => { if (event.target.matches('[data-tree-label], [name$="[label]"]')) refreshParents(); }); refreshParents();
})();
</script>
